  email: 'a@b.com',
  password: 'password123'
}

function getFormData() {
  // Step 1: Find the email input by its id
  let emailElement = document.getElementById('email')
  // Read the text inside it
  let emailValue = emailElement.value  // → 'a@b.com'

  // Step 2: Find the password input
  let passwordElement = document.getElementById('password')
  let passwordValue = passwordElement.value  // → 'password123'

  // Step 3: Return them grouped as an object
  return { email: emailValue, password: passwordValue }
}

// When you call getFormData(), it returns:
// { email: 'a@b.com', password: 'password123' }

