lesson.content:
// Without validation, users could submit anything:
//   Email: ''  (blank!)
//   Password: '123'  (too short!)
// 
// Validation catches these BEFORE they cause problems.

let messy = '   hello   '
let clean = messy.trim()
console.log(clean)  // → 'hello'  (spaces are gone!)

// Before checking if something is empty, ALWAYS trim first:
let input = '   '
if (input.trim() === '') {
  console.log('This is empty!')  // → This is empty!
}
// Without .trim(), '   ' wouldn't be seen as empty

let email1 = 'hello@gmail.com'
console.log(email1.includes('@'))  // → true   (has @)

let email2 = 'notanemail'
console.log(email2.includes('@'))   // → false  (no @!)

// Real email check:
if (!email.includes('@')) {
  return 'Invalid email format'
}

function checkAge(age) {
  if (age < 0) {
    return 'Age cannot be negative'
  }
  if (age < 18) {
    return 'Too young'
  }
  return 'Allowed'
}

console.log(checkAge(-5))  // → 'Age cannot be negative' (stops here!)
console.log(checkAge(15))  // → 'Too young'
console.log(checkAge(25))  // → 'Allowed' (passed every check)

function validateLogin(email, password) {
  // Check 1: Is email empty after removing spaces?
  if (email.trim() === '') {
    return 'Email is required'
  }

  // Check 2: Is password empty after removing spaces?
  if (password.trim() === '') {
    return 'Password is required'
  }

  // Check 3: Does the email contain an @ symbol?
  if (!email.includes('@')) {
    return 'Invalid email format'
  }

  // Check 4: Is the password at least 6 characters long?
  if (password.length < 6) {
    return 'Password must be at least 6 characters'
  }

  // All checks cleared!
  return 'valid'
}

console.log(validateLogin('', 'pass123'))       // → 'Email is required'
console.log(validateLogin('a@b.com', ''))       // → 'Password is required'
console.log(validateLogin('bad', 'pass123'))    // → 'Invalid email format'
console.log(validateLogin('a@b.com', '12345'))  // → 'Password must be at least 6 characters'
console.log(validateLogin('a@b.com', 'hello'))  // → 'Password must be at least 6 characters'
console.log(validateLogin('a@b.com', 'abcdef')) // → 'valid'

