lesson.content:
// Find the form
let form = document.getElementById('login-form')

// Listen for when someone tries to submit it
form.addEventListener('submit', function(e) {
  // This code runs when the form is submitted
  console.log('Form was submitted!')
})
// Now when Submit is clicked, "Form was submitted!" appears
// But the page still reloads! We need to fix that next...

form.addEventListener('submit', function(e) {
  e.preventDefault()  // CRITICAL: stops page reload!

  console.log('The page did NOT reload!')
  // Without e.preventDefault(), the page would refresh
  // and you'd never see this message
})

form.addEventListener('submit', function(e) {
  e.preventDefault()  // Step 1: Stop page reload

  // Step 2: Read the values from the inputs
  let email = document.getElementById('login-email').value
  let password = document.getElementById('login-password').value

  // Step 3: Show something on the page
  let result = document.getElementById('result')
  result.textContent = 'Email: ' + email + ', Password: ' + password
  // The page now shows: "Email: a@b.com, Password: password123"
})

function handleSubmit() {
  // Step 1: Find the form
  let form = document.getElementById('login-form')

  // Step 2: Find the result display area
  let result = document.getElementById('result')

  // Step 3: Tell the form to listen for submit
  form.addEventListener('submit', function(e) {
    e.preventDefault()  // Stop the page from reloading!

    // Step 4: Read the email and password
    let email = document.getElementById('login-email').value
    let password = document.getElementById('login-password').value

    // Step 5: Show the result on the page
    result.textContent = 'Email: ' + email + ', Password: ' + password
  })
}

// When handleSubmit() runs, it sets up everything.
// Now clicking Submit will show the info without reloading!

